head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst01411";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — etnOvrvw, etnProdInfo, etnIdxMktInfo

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst01411.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "a_88", attr: "src", fn: function () { return String(dma_etnProdInfo.get("hpage")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_16_txt", fn: function(){ return (!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_17", fn: function(){ return (!((!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_21_txt", fn: function(){ return (!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_22", fn: function(){ return (!((!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_27_txt", fn: function(){ return (!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_28", fn: function(){ return (!((!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_32_txt", fn: function(){ return (!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_33", fn: function(){ return (!((!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_38_txt", fn: function(){ return (!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_39", fn: function(){ return (!((!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_43_txt", fn: function(){ return (!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_44", fn: function(){ return (!((!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_49_txt", fn: function(){ return (!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_50", fn: function(){ return (!((!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_54_txt", fn: function(){ return (!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_55", fn: function(){ return (!((!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_60_txt", fn: function(){ return (!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_61", fn: function(){ return (!((!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_65_txt", fn: function(){ return (!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_66", fn: function(){ return (!((!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)))); } }, { id: "c_when_71_txt", fn: function(){ return (!(String(((dma_pageContext.get("etnProdInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etnProdInfo") ?? ""))).length === 0)); } }, { id: "c_otherwise_72", fn: function(){ return (!((!(String(((dma_pageContext.get("etnProdInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etnProdInfo") ?? ""))).length === 0)))); } }, { id: "c_when_76_txt", fn: function(){ return (!(String(((dma_pageContext.get("etnProdInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etnProdInfo") ?? ""))).length === 0)); } }, { id: "c_otherwise_77", fn: function(){ return (!((!(String(((dma_pageContext.get("etnProdInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etnProdInfo") ?? ""))).length === 0)))); } }, { id: "c_when_82_txt", fn: function(){ return (!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_83", fn: function(){ return (!((!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)))); } }, { id: "a_88", fn: function(){ return (!(String(((dma_pageContext.get("etnProdInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etnProdInfo") ?? ""))).length === 0)); } }, { id: "c_otherwise_89", fn: function(){ return (!((!(String(((dma_pageContext.get("etnProdInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etnProdInfo") ?? ""))).length === 0)))); } }, { id: "if_etnOvrvw", fn: function(){ return (!(String(((dma_pageContext.get("etnOvrvw") ?? "")) == null ? '' : ((dma_pageContext.get("etnOvrvw") ?? ""))).length === 0)); } }, { id: "c_otherwise_106", fn: function(){ return (!((!(String(((dma_etnIdxMktInfo.get("mktUpclss") ?? (() => { throw new Error("unresolved:" + "etnIdxMktInfo.mktUpclss"); })())) == null ? '' : ((dma_etnIdxMktInfo.get("mktUpclss") ?? (() => { throw new Error("unresolved:" + "etnIdxMktInfo.mktUpclss"); })()))).length === 0)))); } }, { id: "c_otherwise_111", fn: function(){ return (!((!(String(((dma_etnIdxAsstInfo.get("asstUpclss") ?? (() => { throw new Error("unresolved:" + "etnIdxAsstInfo.asstUpclss"); })())) == null ? '' : ((dma_etnIdxAsstInfo.get("asstUpclss") ?? (() => { throw new Error("unresolved:" + "etnIdxAsstInfo.asstUpclss"); })()))).length === 0)))); } }, { id: "if_etnIdxMktInfo", fn: function(){ return (!(String(((dma_pageContext.get("etnIdxMktInfo") ?? "")) == null ? '' : ((dma_pageContext.get("etnIdxMktInfo") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "a_88", fn: function () { return String(dma_etnProdInfo.get("hpage")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.fnInit();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst01411.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnInit = function () {
    $("#searchForm > #isurCd").val('' + dma_etnOvrvw.get("isurCd") + '');
    $("#searchForm > #comAbbrv").val('' + dma_etnOvrvw.get("comAbbrv") + '');
};
